<?php require __DIR__ . '/includes/config.php'; if(isset($_GET['remove']))unset($_SESSION['wishlist'][(int)$_GET['remove']]);$ids=array_keys($_SESSION['wishlist']??[]);$products=[];if($ids){$marks=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT * FROM products WHERE id IN ($marks)");$s->execute($ids);$products=$s->fetchAll();}$pageTitle='Wishlist';require __DIR__ . '/includes/header.php'; ?><section class="container py-5"><div class="eyebrow">Saved for later</div><h1 class="display-5 mb-4">Wishlist</h1><div class="row g-4"><?php foreach($products as $product): ?><div class="col-sm-6 col-lg-3"><article class="card product-card"><img class="card-img-top product-img" src="<?= e($product['image']) ?>" alt=""><div class="card-body"><h2 class="h5"><?= e($product['name']) ?></h2><div class="price">$<?= number_format((float)$product['price'],2) ?></div><a class="btn btn-sm btn-outline-dark mt-3" href="product.php?id=<?= $product['id'] ?>">View product</a><a class="d-block mt-2 small text-danger" href="?remove=<?= $product['id'] ?>">Remove</a></div></article></div><?php endforeach; ?></div><?php if(!$products): ?><div class="panel">Nothing saved yet. <a href="index.php">Browse the collection.</a></div><?php endif; ?></section><?php require __DIR__ . '/includes/footer.php'; ?>